CREATE ALGORITHM=UNDEFINED SQL SECURITY INVOKER VIEW `v_items_overview` AS select `i`.`item_id` AS `item_id`,`i`.`item_type` AS `item_type`,`i`.`title` AS `title`,`i`.`description` AS `description`,`i`.`location_detail` AS `location_detail`,`i`.`event_date` AS `event_date`,`i`.`event_time` AS `event_time`,`i`.`created_at` AS `created_at`,`i`.`updated_at` AS `updated_at`,`i`.`resolved_at` AS `resolved_at`,`u`.`user_id` AS `reporter_user_id`,`u`.`full_name` AS `reporter_name`,`c`.`category_id` AS `category_id`,`c`.`category_name` AS `category_name`,`l`.`location_id` AS `location_id`,`l`.`location_code` AS `location_code`,`l`.`location_name` AS `location_name`,`l`.`location_kind` AS `location_kind`,`b`.`building_id` AS `building_id`,`b`.`building_name` AS `building_name`,`lf`.`location_floor_id` AS `location_floor_id`,`lf`.`floor_name` AS `floor_name`,`st`.`status_id` AS `status_id`,`st`.`status_code` AS `status_code`,`st`.`status_name` AS `status_name` from ((((((`items` `i` join `users` `u` on(`u`.`user_id` = `i`.`reporter_user_id`)) join `categories` `c` on(`c`.`category_id` = `i`.`category_id`)) join `item_statuses` `st` on(`st`.`status_id` = `i`.`status_id`)) left join `campus_locations` `l` on(`l`.`location_id` = `i`.`location_id`)) left join `buildings` `b` on(`b`.`building_id` = `l`.`building_id`)) left join `location_floors` `lf` on(`lf`.`location_floor_id` = `i`.`location_floor_id`));

CREATE ALGORITHM=UNDEFINED SQL SECURITY INVOKER VIEW `v_pending_claims` AS select `cl`.`claim_id` AS `claim_id`,`cl`.`item_id` AS `item_id`,`cl`.`related_lost_item_id` AS `related_lost_item_id`,`cl`.`claimant_user_id` AS `claimant_user_id`,`claimant`.`full_name` AS `claimant_name`,`claimant`.`email` AS `claimant_email`,`cl`.`ownership_answer` AS `ownership_answer`,`cl`.`claim_status` AS `claim_status`,`cl`.`created_at` AS `created_at`,`cl`.`updated_at` AS `updated_at`,`i`.`title` AS `item_title`,`i`.`item_type` AS `item_type`,`i`.`verification_clue` AS `verification_clue`,`reporter`.`full_name` AS `reporter_name`,`c`.`category_name` AS `category_name`,`l`.`location_name` AS `location_name`,`i`.`location_detail` AS `location_detail`,`lost`.`title` AS `related_lost_title`,`lost`.`verification_clue` AS `related_lost_verification_clue`,(select count(0) from `claim_photos` `cp` where `cp`.`claim_id` = `cl`.`claim_id`) AS `claim_photo_count`,(select count(0) from `item_photos` `ip` where `ip`.`item_id` = `cl`.`related_lost_item_id` and `ip`.`photo_kind` = 'OWNERSHIP') AS `related_lost_photo_count` from ((((((`claims` `cl` join `items` `i` on(`i`.`item_id` = `cl`.`item_id`)) join `users` `claimant` on(`claimant`.`user_id` = `cl`.`claimant_user_id`)) join `users` `reporter` on(`reporter`.`user_id` = `i`.`reporter_user_id`)) join `categories` `c` on(`c`.`category_id` = `i`.`category_id`)) left join `campus_locations` `l` on(`l`.`location_id` = `i`.`location_id`)) left join `items` `lost` on(`lost`.`item_id` = `cl`.`related_lost_item_id`)) where `cl`.`claim_status` in ('PENDING','NEED_MORE_INFO');
